 3	public final class LongestCommonSubsequence {
 4	    private static final String SAMPLE_FIRST = "AGGTAB";
 5	    private static final String SAMPLE_SECOND = "GXTXAYB";
 6	    private static final int REQUIRED_ARGUMENT_COUNT = 2;
 7	
 8	    private LongestCommonSubsequence() {
 9	    }
10	
11	    public static int lcs(String first, String second) {
12	        Objects.requireNonNull(first, "first must not be null");
13	        Objects.requireNonNull(second, "second must not be null");
14	
15	        if (first.isEmpty() || second.isEmpty()) {
16	            return 0;
17	        }
18	
19	        if (first.equals(second)) {
20	            return first.length();
21	        }
22	
23	        return new Solver(first, second).solve();
24	    }
25	
26	    public static void main(String[] args) {
27	        if (args.length == REQUIRED_ARGUMENT_COUNT) {
28	            System.out.println(lcs(args[0], args[1]));
29	            return;
30	        }
31	
32	        System.out.println(lcs(SAMPLE_FIRST, SAMPLE_SECOND));
33	    }
34	
35	    private static final class Solver {
36	        private final char[] longer;
37	        private final char[] shorter;
38	        private final int[] lengths;
39	
40	        private Solver(String first, String second) {
41	            char[] firstChars = first.toCharArray();
42	            char[] secondChars = second.toCharArray();
43	
44	            if (firstChars.length >= secondChars.length) {
45	                this.longer = firstChars;
46	                this.shorter = secondChars;
47	            } else {
48	                this.longer = secondChars;
49	                this.shorter = firstChars;
50	            }
51	
52	            this.lengths = new int[this.shorter.length + 1];
53	        }
54	
55	        private int solve() {
56	            for (char current : longer) {
57	                updateLengths(current);
58	            }
59	
60	            return lengths[shorter.length];
61	        }
62	
63	        private void updateLengths(char current) {
64	            int diagonal = 0;
65	
66	            for (int j = 1; j <= shorter.length; j++) {
67	                int previousRow = lengths[j];
68	
69	                lengths[j] = current == shorter[j - 1]
70	                    ? diagonal + 1
71	                    : Math.max(lengths[j], lengths[j - 1]);
72	                diagonal = previousRow;
73	            }
74	        }
75	    }
76	}

